public sealed class PassiveBallProbe:MonoBehaviour {public int zhaoHead;void OnCollisionEnter2D(Collision2D c){See(c);}void OnCollisionStay2D(Collision2D c){See(c);}void See(Collision2D c){if(c.collider!=null&&c.collider.name=="Head"&&c.collider.GetComponentInParent<SkillRework>()!=null&&c.collider.GetComponentInParent<SkillRework>().name=="Zhao")zhaoHead++;}}

public sealed class HookTouchProbe:MonoBehaviour {public int contacts;void OnCollisionEnter2D(Collision2D c){if(c.collider.GetComponentInParent<SkillRework>()!=null)contacts++;}}

public sealed class TouchSequenceProbe:MonoBehaviour{int fan,zhao;public int Count(string name){return name=="Fan"?fan:zhao;}void See(Collision2D c){var actor=c.collider.GetComponentInParent<SkillRework>();if(actor==null)return;if(actor.name=="Fan")fan++;else if(actor.name=="Zhao")zhao++;}void OnCollisionEnter2D(Collision2D c){See(c);}void OnCollisionStay2D(Collision2D c){See(c);}}
